import sys, os, re, struct, time
os.environ.setdefault('TMPDIR','/dev/shm/pt')
sys.path.insert(0,'/tmp/kit')
from elfkit import *
import multiprocessing as mp

CHUNK = 30000
BITS = 32
PHES = 32
EHSZ = 52

def build_file(vals, filesz=0x40):
    base = EHSZ + PHES*len(vals)
    off = (base + 0x200) & ~0xff
    fsize = off + 0x200
    phdrs=[dict(ptype=v, off=off, filesz=filesz) for v in vals]
    return build(phdrs=phdrs, filesize=fsize, bits=BITS, endian=1)

RX = re.compile(r"id='info_(phdr|segment)(\d+)'>\n          <th colspan='2' class='\w+'></th>\n            <tr> <td>Type:</td> <td>(.*?)</td> </tr>")

def probe(vals):
    """returns dict of anomalies value->(phdrstr, segstr); raises on panic"""
    h = run(build_file(vals))
    if h is None:
        raise RuntimeError(run.err.strip())
    n = len(vals)
    if h.count("Unknown: ") == 2*n and h.count("<td>Type:</td>") == 2*n:
        return {}
    ph={}; sg={}
    for m in RX.finditer(h):
        (ph if m.group(1)=='phdr' else sg)[vals[int(m.group(2))]] = m.group(3)
    out={}
    for v in vals:
        a=ph.get(v); b=sg.get(v)
        if a != 'Unknown: %d' % v or b != a:
            out[v]=(a,b)
    return out

def probe_safe(vals):
    try:
        return probe(vals)
    except Exception as e:
        if len(vals)==1:
            return {vals[0]: ('PANIC', str(e).replace('\n','|')[:300])}
        h=len(vals)//2
        r=probe_safe(vals[:h]); r.update(probe_safe(vals[h:]))
        return r

def worker(args):
    lo,hi = args
    out={}
    v=lo
    while v < hi:
        vals=list(range(v, min(v+CHUNK, hi)))
        out.update(probe_safe(vals))
        v += CHUNK
    return out

def sweep(lo, hi, nproc=48, span=None):
    if span is None:
        span = max(CHUNK, (hi-lo)//(nproc*4)//CHUNK*CHUNK or CHUNK)
    tasks=[(a, min(a+span,hi)) for a in range(lo,hi,span)]
    res={}
    with mp.Pool(nproc) as p:
        for i,r in enumerate(p.imap_unordered(worker, tasks)):
            res.update(r)
            if i%50==0: sys.stderr.write("\r%d/%d"%(i,len(tasks))); sys.stderr.flush()
    sys.stderr.write("\n")
    return res

if __name__ == '__main__':
    lo=int(sys.argv[1],0); hi=int(sys.argv[2],0)
    np_=int(sys.argv[3]) if len(sys.argv)>3 else 48
    t=time.time()
    r=sweep(lo,hi,np_)
    print("# swept 0x%x..0x%x in %.1fs, %d anomalies"%(lo,hi,time.time()-t,len(r)))
    for v in sorted(r): print("0x%08x %-12d %r" % (v,v,r[v]))
